package matteroverdrive.client.screen;import matteroverdrive.menu.ContractMarketMenu;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.inventory.AbstractContainerScreen;import net.minecraft.network.chat.Component;import net.minecraft.world.entity.player.Inventory;
public class ContractMarketScreen extends AbstractContainerScreen<ContractMarketMenu>{public ContractMarketScreen(ContractMarketMenu m,Inventory i,Component t){super(m,i,t);imageWidth=176;imageHeight=191;inventoryLabelY=78;}@Override public void render(GuiGraphics g,int x,int y,float p){renderBackground(g);super.render(g,x,y,p);renderTooltip(g,x,y);}@Override protected void renderBg(GuiGraphics g,float p,int x,int y){MachineScreenStyle.drawFrame(g,leftPos,topPos,imageWidth,imageHeight,inventoryLabelY,MachineScreenStyle.CYAN);MachineScreenStyle.drawSection(g,leftPos+17,topPos+29,142,38);for(int i=0;i<3;i++)MachineScreenStyle.drawSlot(g,leftPos+43+i*36,topPos+37);}@Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,8,9,MachineScreenStyle.TEXT,false);g.drawString(font,"Take a contract. Redeem it here when complete.",20,31,MachineScreenStyle.MUTED,false);g.drawString(font,playerInventoryTitle,8,inventoryLabelY,MachineScreenStyle.MUTED,false);}}